mapper.update:
UPDATE community_post
SET VIEW_COUNT = VIEW_COUNT + 1
WHERE POST_ID = #{postId}

mapper.insert:
INSERT INTO community_post
( USER_ID
, CATEGORY
, TITLE
, CONTENT
, CREATE_DT
) VALUES
( #{userId}
, #{category}
, #{title}
, #{content}
, NOW() )

INSERT INTO community_comment
( POST_ID
, USER_ID
, CONTENT
, CREATE_DT
) VALUES
( #{postId}
, #{userId}
, #{content}
, NOW() )

mapper.select:
SELECT count(cp.POST_ID)
  FROM community_post cp
 WHERE cp.USER_ID = #{userId}
   AND cp.POST_ID = #{postId}
   AND cp.DELETE_YN = 'N'

SELECT count(cc.COMMENT_ID)
  FROM community_comment cc
 WHERE cc.USER_ID = #{userId}
   AND cc.COMMENT_ID = #{commentId}
   AND cc.DELETE_YN = 'N'
